def puisi(r, tema=None, n=None):
    tema = tema or r.choice(list(TEMA))
    lines = TEMA[tema]
    n = n or r.choice([4, 5, 6, 8])
    pick = sorted(r.sample(range(len(lines)), min(n, len(lines))))
    chosen = [lines[i] for i in pick]
    out = []
    for i, ln in enumerate(chosen):
        end = "." if i == len(chosen) - 1 else r.choice([",", ",", ";"])
        out.append(ln + end)
    title = tema.capitalize() if r.random() < 0.5 else "Sajak " + tema
    return tema, title, "\n".join(out)
